/**  What to do with a message that arrives while a turn is running. */
export type SendMode = 
/**  Deliver it as its own turn once the running one ends. */
"queue" | 
/**
 *  Feed it into the running turn. Falls back to queueing when the provider
 *  cannot steer.
 */
"steer";

/**  A setting of a plugin's own. Every value is text. */
export type SettingField = {
	/**  Letters, digits, `-` and `_`; unique within the plugin. */
	id: string,
	label: string,
	description?: string | null,
	kind: SettingKind,
	/**  What the plugin is told while the user has not set it. */
	default?: string | null,
};

/**  What a plugin's setting holds, which also says how a client asks for it. */
export type SettingKind = { type: "text" } | 
/**  `true` or `false`. */
{ type: "flag" } | { type: "choice"; options: string[] } | 
/**  The id of an agent provider. */
{ type: "provider" } | 
/**  A model of the provider the setting `provider` holds. */
{ type: "model"; provider: string } | 
/**
 *  An effort level of the model the setting `model` holds, for the provider
 *  the setting `provider` holds.
 */
{ type: "effort"; provider: string; model: string } | { type: "permission-mode" };

/**  What the user set for the daemon. Kept in `<data>/settings.json`. */
export type Settings = {
	/**  The agent a new thread gets when none is named. */
	default_provider?: ProviderId | null,
	/**
	 *  Where the programs plugins run live, by the name a plugin runs them by
	 *  (`claude` → `/opt/claude/bin/claude`). A name not here is looked up on the
	 *  daemon's `PATH`.
	 */
	programs?: { [key in string]: string },
	providers?: { [key in ProviderId]: ProviderSettings },
	/**
	 *  MCP servers every agent session gets on top of those the agent's own
	 *  configuration names, by server name. A change reaches running sessions the
	 *  way `thread.set_mcp` does.
	 */
	mcp_servers?: { [key in string]: McpServerSettings },
	/**  What the user set for skills plugins offer, by skill name. */
	skills?: { [key in string]: SkillSettings },
	/**
	 *  The values of plugins' own settings (`PluginInfo::settings`): by plugin id,
	 *  then by setting id. A setting not here has its default.
	 */
	plugins?: { [key in string]: { [key in string]: string } },
	/**
	 *  Plugins turned off, by id, sorted. Changed only by `plugin.enable` and
	 *  `plugin.disable`, which start and stop them: `settings.set` keeps it as it is.
	 */
	disabled_plugins?: string[],
};

export type SettingsResult = {
	settings: Settings,
	/**  Every program plugins may run, by name. */
	programs: ProgramStatus[],
};

export type SettingsSetParams = {
	settings: Settings,
};

export type SkillListResult = {
	/**  By name. */
	skills: SkillStatus[],
};

export type SkillSettings = {
	/**  No session gets it, whatever a thread asks. */
	disabled?: boolean,
};

export type SkillStatus = {
	name: string,
	description: string,
	/**  The plugin that offers it. */
	plugin: string,
	/**  Given only to threads that ask for it, not to every session. */
	on_request?: boolean,
	/**  Turned off in the settings: no session gets it. */
	disabled?: boolean,
	/**  Where agents read it. */
	path: string,
};

export type StopMode = 
/**  Settle the running turn as interrupted; the session stays attached. */
"interrupt" | 
/**  Also detach the provider session. The thread can be resumed by sending input. */
"release";

/**
 *  The unit of work: one conversation with one provider in one working directory.
 * 
 *  This is a projection: every field after creation changes only through
 *  [`Thread::apply`], so replaying the journal rebuilds it exactly.
 */
export type Thread = {
	id: ThreadId,
	provider: ProviderId,
	/**
	 *  Where the agent works. For a thread with an environment this is the source
	 *  directory until the environment is ready.
	 */
	cwd: string,
	/**  Absent: the thread works directly in `cwd`. */
	environment?: ThreadEnvironment | null,
	model?: string | null,
	/**
	 *  How hard the model thinks, as its provider names the level. Absent: the
	 *  agent's own default.
	 */
	effort?: string | null,
	parent?: ThreadId | null,
	/**
	 *  The thread whose agent started this one on the user's behalf, as a thread
	 *  of the user's own rather than a child: it is not under it and not held to
	 *  its permission mode.
	 */
	started_by?: ThreadId | null,
	/**
	 *  A thread a plugin keeps for its own use: clients leave it out of their
	 *  lists and overviews, and reach it by its id.
	 */
	hidden?: boolean,
	/**
	 *  The automation that started the thread on its schedule. The automation may
	 *  have been deleted since.
	 */
	automation?: AutomationId | null,
	/**  The project the thread is grouped under. */
	project?: ProjectId | null,
	/**  Absent: the agent's own configuration decides what it may do unasked. */
	permission_mode?: PermissionMode | null,
	title?: string | null,
	status: ThreadStatus,
	/**  The provider's durable session handle, used to resume after a restart. */
	provider_session?: string | null,
	/**  Milliseconds since the Unix epoch. */
	created_at: number,
	updated_at: number,
	/**  Sequence number of the last event applied. */
	last_seq: number,
	/**  Messages waiting for the running turn to end. */
	queued_inputs?: number,
	/**  Approvals and questions the agent is waiting on, oldest first. */
	pending_interactions?: PendingInteraction[],
	/**  The latest item, in one line. */
	activity?: ThreadActivity | null,
	/**  When the running turn started, in milliseconds since the Unix epoch. */
	turn_started_at?: number | null,
	/**  How the latest turn ended. Absent while one runs and before the first. */
	last_turn_status?: TurnStatus | null,
	/**
	 *  When the latest turn ended, in milliseconds since the Unix epoch: what a
	 *  client compares with what the user has seen.
	 */
	last_turn_at?: number | null,
	/**  Tokens spent, how full the context is, how turns ended. */
	usage?: ThreadUsage,
	/**
	 *  What the context window holds, part by part, as the agent last said; without
	 *  the entries of each part. Absent for agents that do not say and after the
	 *  conversation started afresh.
	 */
	context?: ContextUsage | null,
	/**
	 *  The MCP servers of the current session as its agent reports them, in the
	 *  order they were first reported. Empty until it says and for agents that do not.
	 */
	mcp_servers?: McpServerStatus[],
	/**
	 *  MCP servers set up in qcc that this thread keeps off, by name, sorted: its
	 *  sessions start without them. Not passed on to the threads it starts.
	 */
	mcp_disabled?: string[],
	/**  Skills offered on request that this thread gets, by name, sorted. */
	skills_enabled?: string[],
	/**
	 *  Skills every session gets that this thread goes without, by name, sorted.
	 *  Neither list is passed on to the threads it starts.
	 */
	skills_disabled?: string[],
	/**  How many times the conversation was started afresh (`thread/reset`). */
	conversations?: number,
	/**  Put away: it takes no more input and is left out of listings. */
	archived?: boolean,
	/**
	 *  The provider changed, or the thread moved into an environment, since the
	 *  last session started. The next session has nothing to resume and is told
	 *  the conversation so far instead.
	 */
	handover?: boolean,
};

/**
 *  The latest item of a thread, cut down to one line: enough to tell at a glance
 *  what the agent is doing without reading its timeline.
 */
export type ThreadActivity = {
	kind: ActivityKind,
	/**
	 *  The command, path, query or tool name; for text, its first line once the
	 *  item has settled. Never longer than [`ACTIVITY_MAX_CHARS`] characters.
	 */
	detail: string,
	status: ItemStatus,
};

